<?php $title = 'پرونده مشتری'; ?>
<div class="card"><form method="get" action="<?= e(base_url('accounting/customer')) ?>" class="searchbar"><div><label>انتخاب مشتری</label><select name="customer_id" required><option value="">انتخاب کنید</option><?php foreach($customers as $c): ?><option value="<?= e($c['id']) ?>" <?= ($customer && (int)$customer['id']===(int)$c['id'])?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select></div><button class="btn">نمایش پرونده</button></form></div>
<?php if($customer): ?><div class="grid"><div class="col-4 card"><h2><?= e($customer['name']) ?></h2><p>تلفن: <?= e($customer['phone']) ?></p><p>آدرس: <?= e($customer['address']) ?></p></div><div class="col-8 card"><h2>فاکتورهای فروش</h2><div class="table-wrap"><table class="table compact-table"><tr><th>تاریخ</th><th>شماره</th><th>جمع</th><th>پرداختی</th><th>مانده</th></tr><?php foreach($invoices as $i): ?><tr><td><?= e(jalali_like_date($i['invoice_date'])) ?></td><td><?= e($i['invoice_no']) ?></td><td><?= e(number_format((float)$i['total'])) ?></td><td><?= e(number_format((float)$i['paid_amount'])) ?></td><td><?= e(number_format((float)$i['total']-(float)$i['paid_amount'])) ?></td></tr><?php endforeach; ?></table></div></div><div class="col-12 card"><h2>گردش حساب مشتری</h2><div class="table-wrap"><table class="table"><tr><th>تاریخ</th><th>سند</th><th>بدهکار</th><th>بستانکار</th><th>شرح</th></tr><?php foreach($journals as $j): ?><tr><td><?= e(jalali_like_date($j['entry_date'])) ?></td><td><?= e($j['entry_no']) ?></td><td><?= e(number_format((float)$j['debit'])) ?></td><td><?= e(number_format((float)$j['credit'])) ?></td><td><?= e($j['memo']) ?></td></tr><?php endforeach; ?></table></div></div></div><?php endif; ?>
